use strict;
use warnings;

my ($a1, $b1) = (17, 5);
print "add: ", $a1 + $b1, "\n";
print "sub: ", $a1 - $b1, "\n";
print "mul: ", $a1 * $b1, "\n";
print "div: ", $a1 / $b1, "\n";
print "int div: ", int($a1 / $b1), "\n";
print "mod: ", $a1 % $b1, "\n";
print "pow: ", $a1 ** 3, "\n";
print "10/4 = ", 10 / 4, "\n";
print "10/5 = ", 10 / 5, "\n";
print "2**10 = ", 2 ** 10, "\n";
print "2**-1 = ", 2 ** -1, "\n";
printf "sqrt2 via ** : %.6f\n", 2 ** 0.5;
printf "sqrt(144) = %s\n", sqrt(144);
print "abs(-7.5) = ", abs(-7.5), "\n";
print "int(3.7) = ", int(3.7), " int(-3.7) = ", int(-3.7), "\n";
printf "round half: %.0f %.0f %.0f %.0f\n", 0.5, 1.5, 2.5, -2.5;
printf "%.17f\n", 0.1 + 0.2;
print(((0.1 + 0.2) == 0.3) ? "float equal\n" : "float not equal\n");
printf "%.10g\n", 0.1 + 0.2;
my $acc = 0;
$acc += $_ for 1 .. 10;
print "sum 1..10 = $acc\n";
my $prod = 1;
$prod *= $_ for 1 .. 10;
print "10! = $prod\n";
print "big: ", 2 ** 53, "\n";
print "bigger: ", 2 ** 62, "\n";
